#!/usr/bin/env node
// @check node — Every generated file is one merge-main.mjs rebuilds: each build output and each file headed "generated" is in its GENERATED list, each file-writing build script is a BUILD step or says why not
// A generated file merge-main.mjs does not know is merged by hand, and two branches collide on it every time (that is
// how docs/INVENTORY.md and js/cm-deck-slides.js kept conflicting). This check fails the moment a generator is added
// without being listed in .github/scripts/merge-main.mjs:
//   1. every BUILD step and every NOT_REBUILT script exists;
//   2. every script under build/ that writes files is a BUILD step or in NOT_REBUILT (with the reason);
//   3. every file whose header says it is generated / not to be edited by hand matches GENERATED;
//   4. the BUILD steps, run in a scratch copy of the repository, write only files GENERATED lists (and the sources the
//      terms pass recapitalizes), and every GENERATED pattern is written by one of them.
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { GENERATED, BUILD, NOT_REBUILT, isGenerated } from './merge-main.mjs';

const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), '../..');
const problems = [];
const files = execFileSync('git', ['ls-files', '-co', '--exclude-standard'], { cwd: ROOT, encoding: 'utf8' })
  .split('\n').filter((f) => f && !/^\.claude\//.test(f) && fs.existsSync(path.join(ROOT, f)));

// 1.
for (const s of [...BUILD, ...Object.keys(NOT_REBUILT)]) if (!fs.existsSync(path.join(ROOT, s))) problems.push(`${s} is named in merge-main.mjs but does not exist`);

// 2.
const WRITES = /writeFileSync|createWriteStream|write_text|write_bytes|\.save\(|open\([^)]*["']w/;
for (const f of files.filter((f) => /^build\/.*\.(c|m)?js$|^build\/.*\.py$/.test(f))) {
  if (WRITES.test(fs.readFileSync(path.join(ROOT, f), 'utf8')) && !BUILD.includes(f) && !NOT_REBUILT[f])
    problems.push(`${f} writes files but is neither a BUILD step in merge-main.mjs nor in its NOT_REBUILT list`);
}

// 3. the markers the generators stamp in their output's first lines ("GENERATED by", "Generated from `…`", "Do not edit
//    here", "never edit this file by hand"); the generators' own sources (build/), the checks (.github/) and a file that
//    says it is "not generated" / "HAND-AUTHORED" are not outputs
const HEADER = /\bGENERATED by\b|\bGenerated (by|from) `|Do not (hand-)?edit (here|by hand|this file)|never edit this file by hand/i;
for (const f of files.filter((f) => /\.(m?js|cjs|md|html?|css|json)$/.test(f) && !/^(build|\.github)\//.test(f))) {
  const lines = fs.readFileSync(path.join(ROOT, f), 'utf8').split('\n');
  const head = lines.slice(0, 20).join('\n'), top = lines.slice(0, 6).join('\n');
  if (HEADER.test(head) && !/HAND-AUTHORED|\bnot generated\b/i.test(top) && !isGenerated(f))
    problems.push(`${f} says it is generated, but merge-main.mjs GENERATED does not list it`);
}

// 4. a scratch copy: text files copied, media as empty placeholders (the builds only check those exist)
const TMP = fs.mkdtempSync(path.join(os.tmpdir(), 'merge-main-generated-'));
try {
  const MEDIA = /\.(webp|png|jpe?g|gif|pdf|mp4|mp3|m4a|wav|docx|xlsx|pptx|woff2?|ttf|zip|ico)$/i;
  for (const f of files) {
    const to = path.join(TMP, f);
    fs.mkdirSync(path.dirname(to), { recursive: true });
    if (MEDIA.test(f)) fs.writeFileSync(to, ''); else fs.copyFileSync(path.join(ROOT, f), to);
  }
  const stamp = () => {
    const m = new Map();
    const walk = (d) => { for (const n of fs.readdirSync(d, { withFileTypes: true })) { const p = path.join(d, n.name);
      if (n.isDirectory()) walk(p); else m.set(path.relative(TMP, p).split(path.sep).join('/'), fs.statSync(p).mtimeMs); } };
    walk(TMP); return m;
  };
  const past = Date.now() - 60000;
  for (const f of files) fs.utimesSync(path.join(TMP, f), past / 1000, past / 1000);
  const before = stamp();
  for (const s of BUILD) {
    try { execFileSync(process.execPath, [path.join(TMP, s)], { cwd: TMP, encoding: 'utf8', stdio: 'pipe' }); }
    catch (e) { problems.push(`${s} failed in a scratch copy of the repository: ${(e.stderr || e.message).trim().split('\n').slice(-3).join(' ')}`); }
  }
  const written = [...stamp()].filter(([f, t]) => before.get(f) !== t).map(([f]) => f);
  // the terms pass rewrites the sources themselves (only when a spelling is off, which terms.cjs --check reports)
  const TERMS_SOURCES = /^js\/cm-case-flow-(data|docs)\.js$|^curriculum\/5-day-flow\/case-file\.md$|^build\/case-flow\/[^/]+\/[^/]+\.json$/;
  for (const f of written) if (!isGenerated(f) && !TERMS_SOURCES.test(f) && !/(^|\/)\.tmp\//.test(f))
    problems.push(`a BUILD step writes ${f}, but merge-main.mjs GENERATED does not list it`);
  for (const re of GENERATED) if (!written.some((f) => re.test(f))) problems.push(`GENERATED lists ${re}, but no BUILD step writes it`);
  console.log(`BUILD steps write ${written.filter(isGenerated).length} generated file(s), all of them listed.`);
} finally { fs.rmSync(TMP, { recursive: true, force: true }); }

if (problems.length) {
  console.error(`merge-main.mjs does not settle every generated file:\n${problems.map((p) => '  • ' + p).join('\n')}`);
  console.error('Add the file to GENERATED and its builder to BUILD in .github/scripts/merge-main.mjs (or the builder to NOT_REBUILT, with why).');
  process.exit(1);
}
console.log(`merge-main.mjs settles every generated file: ${GENERATED.length} pattern(s), ${BUILD.length} build step(s).`);
